import { useState } from 'react'
import { ScrollView, Text, TouchableWithoutFeedback, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { Coins } from 'lucide-react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { Grabber, Button, ScreenTitle } from '@/components'
import { LinearGradient } from 'expo-linear-gradient'
import { CreditProductId } from '@/types'
import { CREDIT_OPTIONS } from '@/constants'

export const PurchaseCreditsScreen = ({
	onPurchase,
	isPurchasing
}: {
	onPurchase: (creditId: CreditProductId) => void
	isPurchasing: boolean
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const [selectedCredit, setSelectedCredit] = useState(CREDIT_OPTIONS[0].id)

	const handleCreditPress = async (creditId: CreditProductId) => {
		if (isPurchasing) return
		setSelectedCredit(creditId)
	}

	return (
		<View style={styles.container(theme)}>
			<Grabber />
			<ScrollView showsVerticalScrollIndicator={false}>
				<ScreenTitle
					title="Purchase credits"
					subtitle="Purchase credits if you're running low this month. Unused credits roll over."
				/>

				<View style={styles.optionsContainer}>
					{CREDIT_OPTIONS.map((option) => {
						const isSelected = selectedCredit === option.id
						return (
							<TouchableWithoutFeedback
								key={option.id}
								onPress={() => handleCreditPress(option.id)}
								style={{ overflow: 'hidden' }}
							>
								<View style={[styles.card(theme, isSelected)]}>
									{isSelected && (
										<LinearGradient
											colors={[
												colors[theme].gray[900],
												colors[theme].gray[700]
											]}
											style={styles.cardBackground}
										/>
									)}
									<View style={styles.cardContent}>
										<View style={styles.creditsRow}>
											<Coins
												size={20}
												color={
													isSelected
														? colors[theme].gray[25]
														: colors[theme].gray[400]
												}
											/>
											<Text style={styles.creditsText(theme, isSelected)}>
												{option.credits}K
											</Text>
										</View>
										{isSelected && (
											<Text style={styles.priceText(theme)}>
												${option.price.toFixed(2)}
											</Text>
										)}
									</View>
								</View>
							</TouchableWithoutFeedback>
						)
					})}
				</View>
			</ScrollView>

			<View style={{ paddingBottom: insets.bottom + 16 }}>
				<Button
					text="Continue"
					onPress={() => onPurchase(selectedCredit)}
					variant="gradient"
					loading={isPurchasing}
				/>
			</View>
		</View>
	)
}

const styles = defineStyles({
	container: (theme: Theme) => ({
		flex: 1,
		backgroundColor: colors[theme].background,
		paddingHorizontal: 20
	}),
	optionsContainer: {
		gap: 12
	},
	card: (theme: Theme, isSelected?: boolean) => ({
		overflow: 'hidden',
		backgroundColor: isSelected
			? colors[theme].gray[900]
			: colors[theme].gray[50],
		borderRadius: 12,
		borderCurve: 'continuous',
		paddingHorizontal: 20,
		paddingVertical: 16
	}),
	cardBackground: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		borderRadius: 11,
		borderCurve: 'continuous'
	},
	cardContent: {
		flexDirection: 'row',
		alignItems: 'center',
		justifyContent: 'space-between'
	},
	creditsRow: {
		flexDirection: 'row',
		alignItems: 'center',
		gap: 12
	},
	creditsText: (theme: Theme, isSelected?: boolean) => ({
		fontSize: 16,
		fontWeight: '500',
		color: isSelected ? colors[theme].gray[25] : colors[theme].gray[400],
		transitionProperty: 'color',
		transitionDuration: '300ms'
	}),
	priceText: (theme: Theme) => ({
		fontSize: 16,
		fontWeight: '600',
		color: colors[theme].gray[25]
	})
})
